}

func metadataSubmoduleWorktrees(t *testing.T) (string, string) {
	t.Helper()
	tmp := t.TempDir()
	subject := filepath.Join(tmp, "subject")
	super := filepath.Join(tmp, "super")
	ordinary := filepath.Join(super, "sub")
