	t.Helper()
	gotInfo, err := os.Stat(got)
	require.NoError(t, err)
	wantInfo, err := os.Stat(want)
	require.NoError(t, err)
	require.Truef(t, os.SameFile(gotInfo, wantInfo), "%s and %s identify different directories", got, want)
}

