const pendingReviewMarkerFilename = "review-pending.json"

// PendingReviewMarker is written by `entire review` before instructing the
// user to open an agent manually. The marker records which agent and
// skills should run so that `entire session attach --review` can tag the
// resulting session after the fact.
//
// WorktreePath scopes the marker to the worktree `entire review` was invoked
// from: multiple worktrees in one repo share .git/entire-sessions/, so without
// this field any session in any worktree could race to claim the marker. A
// blank WorktreePath (pre-fix markers) falls back to the legacy unscoped
// behavior — any session can adopt.
type PendingReviewMarker struct {
	AgentName string   `json:"agent_name"`
	Skills    []string `json:"skills"`
	// Prompt is the composed review prompt the agent will receive.
	// Stored on the marker (rather than recomputed on adoption) so session
	// metadata records exactly what the agent was asked to do.
	Prompt       string    `json:"prompt,omitempty"`
	StartingSHA  string    `json:"starting_sha"`
	StartedAt    time.Time `json:"started_at"`
	WorktreePath string    `json:"worktree_path,omitempty"`
}

// pendingMarkerName is the marker's name inside the git common dir's root.
var pendingMarkerName = session.SessionStateDirName + "/" + pendingReviewMarkerFilename

// pendingMarkerRoot returns the shared *os.Root over the git common dir the
// marker lives in.
func pendingMarkerRoot(ctx context.Context) (*os.Root, error) {
	root, err := gitdir.Open(ctx)
	if err != nil {
		return nil, fmt.Errorf("locate git common dir: %w", err)
	}
	return root, nil
}

// WritePendingReviewMarker persists the marker. Overwrites any existing marker.
func WritePendingReviewMarker(ctx context.Context, m PendingReviewMarker) error {
	root, err := pendingMarkerRoot(ctx)
	if err != nil {
		return err
	}
	if err := osroot.MkdirAllNoSymlink(root, session.SessionStateDirName, 0o750); err != nil {
		return fmt.Errorf("create sessions dir: %w", err)
	}
	data, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal marker: %w", err)
	}
	if err := jsonutil.WriteFileAtomicIn(root, pendingMarkerName, data, 0o600); err != nil {
		return fmt.Errorf("write marker: %w", err)
	}
	return nil
}

// ReadPendingReviewMarker returns the marker if one exists.
// ok=false with err=nil indicates "no pending review."
func ReadPendingReviewMarker(ctx context.Context) (PendingReviewMarker, bool, error) {
	root, err := pendingMarkerRoot(ctx)
	if err != nil {
		return PendingReviewMarker{}, false, err
	}
	data, err := osroot.ReadFileNoFollow(root, pendingMarkerName)
	if errors.Is(err, os.ErrNotExist) {
		return PendingReviewMarker{}, false, nil
	}
	if err != nil {
		return PendingReviewMarker{}, false, fmt.Errorf("read marker: %w", err)
	}
	var m PendingReviewMarker
	if err := json.Unmarshal(data, &m); err != nil {
		return PendingReviewMarker{}, false, fmt.Errorf("parse marker: %w", err)
	}
	return m, true, nil
}

// ClearPendingReviewMarker removes the marker. Missing file is not an error.
func ClearPendingReviewMarker(ctx context.Context) error {
	root, err := pendingMarkerRoot(ctx)
	if err != nil {
		return err
	}
	if err := root.Remove(pendingMarkerName); err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("remove marker: %w", err)
	}
	return nil
}

// RunMarkerFallback handles review for agents that do not yet have an Entire
// review-runner adapter by writing the pending-review marker file and printing
// manual-start guidance. The user is told to open the agent themselves and run
// the configured skills.
//
// The marker is NOT auto-adopted by anything — the lifecycle hook reads
// ENTIRE_REVIEW_* env vars on the spawned process, not the marker file.
// For adapterless review agents the user starts the agent manually, so no env
// inheritance happens. The marker exists purely so that `entire session
// attach --review <session-id>` has a record of what the user was asked to
// review when tagging the session after the fact.
//
// agentName must be the agent's registry key (e.g. "cursor").
// cfg carries skills and the starting SHA.
// worktreePath scopes the marker so sessions in other worktrees don't claim it.
// out is the destination for user-facing guidance.
func RunMarkerFallback(ctx context.Context, agentName string, cfg reviewtypes.RunConfig, worktreePath string, out io.Writer) error {
	prompt := ComposeReviewPrompt(cfg)
	if err := WritePendingReviewMarker(ctx, PendingReviewMarker{
		AgentName:    agentName,
		Skills:       cfg.Skills,
		Prompt:       prompt,
		StartingSHA:  cfg.StartingSHA,
		StartedAt:    time.Now().UTC(),
		WorktreePath: worktreePath,
	}); err != nil {
		return fmt.Errorf("write pending marker: %w", err)
	}

	fmt.Fprintf(out, "%s does not have an Entire review runner adapter yet. Marker written.\n", agentName)
	if len(cfg.Skills) > 0 {
		fmt.Fprintf(out, "Start %s manually and run these skills:\n", agentName)
		for i, skill := range cfg.Skills {
			fmt.Fprintf(out, "  %d. %s\n", i+1, skill)
		}
		fmt.Fprintln(out)
	}
	if prompt != "" {
		fmt.Fprintf(out, "Use this prompt:\n\n%s\n", prompt)
	}
	return nil
}
	return ""
}

func writeLocalReviewManifest(ctx context.Context, manifest LocalReviewManifest) error {
	if len(manifest.Sources) == 0 {
		return errors.New("review manifest has no sources")
	}
	if manifest.Version == 0 {
		manifest.Version = localReviewManifestVersion
	}
	if manifest.CreatedAt.IsZero() {
		manifest.CreatedAt = time.Now()
	}

	root, dir, err := localReviewManifestStore(ctx)
	if err != nil {
		return err
	}
	if err := osroot.MkdirAllNoSymlink(root, dir, 0o700); err != nil {
		return fmt.Errorf("create review manifest dir: %w", err)
	}

	b, err := json.MarshalIndent(manifest, "", "  ")
	if err != nil {
		return fmt.Errorf("encode review manifest: %w", err)
	}
	if err := jsonutil.WriteFileAtomicIn(root, dir+"/"+localReviewManifestFilename(manifest), b, 0o600); err != nil {
		return fmt.Errorf("write review manifest: %w", err)
	}
	return nil
}

func loadLocalReviewManifests(ctx context.Context, worktreeRoot string) ([]LocalReviewManifest, error) {
	root, dir, err := localReviewManifestStore(ctx)
	if err != nil {
		return nil, err
	}
	entries, err := osroot.ReadDirNoSymlinks(root, dir)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("read review manifest dir: %w", err)
	}

	manifests := make([]LocalReviewManifest, 0, len(entries))
	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
			continue
		}
		b, readErr := osroot.ReadFileNoFollow(root, dir+"/"+entry.Name())
		if readErr != nil {
			return nil, fmt.Errorf("read review manifest %s: %w", entry.Name(), readErr)
		}
		var manifest LocalReviewManifest
		if err := json.Unmarshal(b, &manifest); err != nil {
			return nil, fmt.Errorf("decode review manifest %s: %w", entry.Name(), err)
		}
		if worktreeRoot != "" && manifest.WorktreePath != "" && manifest.WorktreePath != worktreeRoot {
			continue
		}
		manifests = append(manifests, manifest)
	}
	sort.SliceStable(manifests, func(i, j int) bool {
		return manifests[i].CreatedAt.After(manifests[j].CreatedAt)
	})
	return manifests, nil
}

// localReviewManifestName is the manifest directory inside the git common dir.
const localReviewManifestName = "entire-review/manifests"

// localReviewManifestStore returns the shared *os.Root over the git common dir
// and the manifest directory's name inside it.
//
// The common-dir resolution comes from gitdir rather than a fourth hand-rolled
// `git rev-parse --git-common-dir` — this file had one, and it was the only copy
// that remembered to resolve a relative answer against the worktree root.
func localReviewManifestStore(ctx context.Context) (*os.Root, string, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, "", fmt.Errorf("resolve worktree root: %w", err)
	}
	commonDir, err := gitdir.CommonDirForWorktree(ctx, worktreeRoot)
	if err != nil {
		return nil, "", fmt.Errorf("resolve git common dir: %w", err)
	}
	root, err := gitdir.OpenAt(commonDir)
	if err != nil {
		return nil, "", fmt.Errorf("open git common dir: %w", err)
	}
	return root, localReviewManifestName, nil
}

func localReviewManifestFilename(manifest LocalReviewManifest) string {
	name := reviewManifestTimeHandle(manifest.CreatedAt)
	if len(manifest.Sources) > 0 && manifest.Sources[0].SessionID != "" {
		name += "-" + safeManifestFilenamePart(manifest.Sources[0].SessionID)
	}
	return name + ".json"
}

func safeManifestFilenamePart(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return "review"
	}
	var b strings.Builder
	for _, r := range value {
		if r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '-' || r == '_' || r == '.' {
			b.WriteRune(r)
			continue
		}
		b.WriteByte('-')
	}
	return b.String()
}
	Stance      string `json:"stance"` // "approve" | "request-changes" | "reject" | "unknown"
	PlanChanged bool   `json:"plan_changed"`
	Note        string `json:"note,omitempty"`
}

// StateStore is the runs-state directory wrapper. The root contains one
// sub-directory per run (named after the run ID), holding findings.md and
// state.json.
type StateStore struct {
	// dir is the absolute store directory. It is kept because RunDir hands
	// absolute paths to callers (the findings doc travels through manifests and
	// into agent prompts); all I/O here is a name inside root.
	dir     string
	parent  string
	dirName string
}

// NewStateStore creates a StateStore rooted at
// <git-common-dir>/entire-investigations. Resolves the common dir via
// session.GetGitCommonDir, so this requires a git repository context.
func NewStateStore(ctx context.Context) (*StateStore, error) {
	commonDir, err := session.GetGitCommonDir(ctx)
	if err != nil {
		return nil, fmt.Errorf("get git common dir: %w", err)
	}
	return &StateStore{
		dir:     filepath.Join(commonDir, InvestigationsDirName),
		parent:  commonDir,
		dirName: InvestigationsDirName,
	}, nil
}

// NewStateStoreWithDir creates a StateStore rooted at dir. Useful for tests
// that don't want to depend on a real git repository.
func NewStateStoreWithDir(dir string) *StateStore {
	return &StateStore{
		dir:     dir,
		parent:  filepath.Dir(dir),
		dirName: filepath.Base(dir),
	}
}

// root returns the shared *os.Root over the directory this store's run
// directories sit inside — the git common dir in production, a temp stand-in
// under test. Run IDs are validated before reaching a path, but resolving them
// as names inside the root is what keeps that a defence rather than the only
// defence: RunDir feeds os.RemoveAll.
func (s *StateStore) root() (*os.Root, error) {
	return gitdir.OpenAt(s.parent) //nolint:wrapcheck // gitdir names the directory and returns a missing one unwrapped for os.IsNotExist
}

// name renders a path under the store as a name relative to root.
func (s *StateStore) name(parts ...string) string {
	return s.dirName + "/" + path.Join(parts...)
}

// RunDir returns the absolute path of the per-run directory for runID,
// where findings.md and state.json both live. The directory may or may
// not exist on disk; callers that need it materialised should MkdirAll
// before writing.
//
// Precondition: runID MUST be a validated 12-hex id. RunDir joins it into a
// path that callers feed to os.RemoveAll (via clean), so an unvalidated id
// would be a path-traversal sink. Every path that reaches here enforces this:
// Save/Load validate before calling; manifest List/ResolveByRunID drop
// manifests whose RunID fails validateRunID before any RunID reaches clean.
func (s *StateStore) RunDir(runID string) string {
	return filepath.Join(s.dir, runID)
}

// Save writes the run state atomically (temp file + rename).
func (s *StateStore) Save(ctx context.Context, st *RunState) error {
	_ = ctx // Reserved for future use

	if err := validateRunID(st.RunID); err != nil {
		return fmt.Errorf("invalid run ID: %w", err)
	}

	root, err := s.root()
	if err != nil {
		return fmt.Errorf("open investigation store: %w", err)
	}
	if err := osroot.MkdirAllNoSymlink(root, s.name(st.RunID), 0o750); err != nil {
		return fmt.Errorf("create investigation run directory: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(st, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal run state: %w", err)
	}

	if err := jsonutil.WriteFileAtomicIn(root, s.runStateName(st.RunID), data, 0o600); err != nil {
		return fmt.Errorf("write run state: %w", err)
	}
	return nil
}

// Load reads the run state for runID. Returns (nil, nil) when the file does
// not exist (treat as "no such run").
func (s *StateStore) Load(ctx context.Context, runID string) (*RunState, error) {
	_ = ctx // Reserved for future use

	if err := validateRunID(runID); err != nil {
		return nil, fmt.Errorf("invalid run ID: %w", err)
	}

	root, err := s.root()
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil //nolint:nilnil // no store => no such run
		}
		return nil, fmt.Errorf("open investigation store: %w", err)
	}
	data, err := osroot.ReadFileNoFollow(root, s.runStateName(runID))
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil //nolint:nilnil // nil,nil indicates run not found
		}
		return nil, fmt.Errorf("read run state: %w", err)
	}

	var st RunState
	if err := json.Unmarshal(data, &st); err != nil {
		return nil, fmt.Errorf("unmarshal run state: %w", err)
	}
	return &st, nil
}

// FindingsPath returns the absolute path of runID's findings document.
// Absolute for the same reason RunStatePath is: the investigating agent writes
// it, and the manifest records where it was.
func (s *StateStore) FindingsPath(runID string) string {
	return filepath.Join(s.RunDir(runID), FindingsFileName)
}

// ReadFindings reads runID's findings document through the store's root.
// A missing document is (nil, false, nil).
func (s *StateStore) ReadFindings(runID string) ([]byte, bool, error) {
	if err := validateRunID(runID); err != nil {
		return nil, false, fmt.Errorf("invalid run ID: %w", err)
	}
	root, err := s.root()
	if err != nil {
		if os.IsNotExist(err) {
			return nil, false, nil
		}
		return nil, false, fmt.Errorf("open investigation store: %w", err)
	}
	data, err := osroot.ReadFileNoFollow(root, s.name(runID, FindingsFileName))
	if err != nil {
		if os.IsNotExist(err) {
			return nil, false, nil
		}
		return nil, false, fmt.Errorf("read findings: %w", err)
	}
	return data, true, nil
}

// WriteFindings writes runID's findings document through the store's root,
// creating the per-run directory. MkdirAllNoSymlink rather than MkdirAll: a
// symlinked component under entire-investigations is a directory Entire did not
// create and cannot vouch for, and this is the write that establishes the run.
func (s *StateStore) WriteFindings(runID string, body []byte) error {
	if err := validateRunID(runID); err != nil {
		return fmt.Errorf("invalid run ID: %w", err)
	}
	root, err := s.root()
	if err != nil {
		return fmt.Errorf("open investigation store: %w", err)
	}
	if err := osroot.MkdirAllNoSymlink(root, s.name(runID), 0o750); err != nil {
		return fmt.Errorf("create investigation run directory: %w", err)
	}
	if err := jsonutil.WriteFileAtomicIn(root, s.name(runID, FindingsFileName), body, 0o600); err != nil {
		return fmt.Errorf("write findings doc: %w", err)
	}
	return nil
}

// ReadRunFindings reads runID's findings document through store.
//
// It exists for the two renderers that hold a LocalManifest and used to read
// m.FindingsDoc directly. That field is an absolute path decoded from a JSON
// file on disk, so following it means a manifest gets to choose which file is
// read and printed. The run id is the part of the manifest that is validated,
// and resolving it as a name inside the store keeps the read in the tree the
// store owns.
//
// Everything is soft: a nil store, an invalid id, a missing run, a missing
// document, and an unreadable one all yield "". The callers print a shorter
// block, and an empty document is indistinguishable from an absent one because
// neither has anything to render.
func ReadRunFindings(store *StateStore, runID string) string {
	if store == nil || !IsValidRunID(runID) {
		return ""
	}
	data, found, err := store.ReadFindings(runID)
	if err != nil || !found {
		return ""
	}
	return string(data)
}

// RemoveRun deletes runID's per-run directory and everything in it.
//
// This is the operation RunDir's doc comment warns about — the one an
// unvalidated id would turn into a path-traversal sink. It resolves runID as a
// NAME inside the store's root rather than joining it into an absolute path, so
// the containment is the kernel's rather than a precondition each caller has to
// keep honouring. validateRunID stays as the layer above it.
//
// A store or run directory that is not there is not an error: clean converges
// when run against a partially removed state.
func (s *StateStore) RemoveRun(runID string) error {
	if err := validateRunID(runID); err != nil {
		return fmt.Errorf("invalid run ID: %w", err)
	}
	root, err := s.root()
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return fmt.Errorf("open investigation store: %w", err)
	}
	if err := root.RemoveAll(s.name(runID)); err != nil {
		return fmt.Errorf("remove run directory: %w", err)
	}
	return nil
}

// RunStatePath returns the absolute path of runID's state file. Absolute on
// purpose: it is handed to the investigating agent, which is a separate process.
// Entire's own reads and writes of the same file go through the root.
func (s *StateStore) RunStatePath(runID string) string {
	return filepath.Join(s.RunDir(runID), stateFileName)
}

// runStateName returns runID's state file as a name relative to root.
func (s *StateStore) runStateName(runID string) string {
	return s.name(runID, stateFileName)
}

// validateRunID enforces that runID is exactly 12 lowercase hex characters.
// Anything else is rejected to prevent path traversal and to keep the format
// stable for sharded directory layouts elsewhere in the codebase.
func validateRunID(runID string) error {
	if runID == "" {
		return errors.New("run ID cannot be empty")
	}
	if !runIDPattern.MatchString(runID) {
		return fmt.Errorf("invalid run ID %q: must be 12 lowercase hex characters", runID)
	}
	return nil
}

// IsValidRunID reports whether runID matches the 12-lowercase-hex format.
// Delegates to provenance.IsValidRunID — the canonical validator lives
// alongside the env-var contract it's most often paired with.
func IsValidRunID(runID string) bool {
	return provenance.IsValidRunID(runID)
}
type LocalManifestStore struct {
	// dir is the absolute manifests directory, kept for messages. All I/O is a
	// name inside root.
	dir     string
	parent  string
	dirName string
}

// NewLocalManifestStore creates a LocalManifestStore rooted at
// <git-common-dir>/entire-investigations/manifests. Resolves the common dir
// via session.GetGitCommonDir, so this requires a git repository context.
func NewLocalManifestStore(ctx context.Context) (*LocalManifestStore, error) {
	commonDir, err := session.GetGitCommonDir(ctx)
	if err != nil {
		return nil, fmt.Errorf("get git common dir: %w", err)
	}
	return &LocalManifestStore{
		dir:     filepath.Join(commonDir, InvestigationsDirName, manifestsSubdirName),
		parent:  commonDir,
		dirName: InvestigationsDirName + "/" + manifestsSubdirName,
	}, nil
}

// NewLocalManifestStoreWithDir creates a LocalManifestStore rooted at dir.
// Useful for tests that do not want to depend on a real git repository.
func NewLocalManifestStoreWithDir(dir string) *LocalManifestStore {
	return &LocalManifestStore{
		dir:     dir,
		parent:  filepath.Dir(dir),
		dirName: filepath.Base(dir),
	}
}

// root returns the shared *os.Root over the directory the manifests sit inside.
func (s *LocalManifestStore) root() (*os.Root, error) {
	return gitdir.OpenAt(s.parent) //nolint:wrapcheck // gitdir names the directory and returns a missing one unwrapped for os.IsNotExist
}

// name renders a manifest file as a name relative to root.
func (s *LocalManifestStore) name(file string) string {
	return s.dirName + "/" + file
}

// Write persists m to the manifests directory using a deterministic filename
// derived from m.StartedAt and m.RunID. Existing files are overwritten — the
// timestamp+run-id combination is unique by construction (each run has a fresh
// run ID and a different start time).
func (s *LocalManifestStore) Write(ctx context.Context, m LocalManifest) error {
	_ = ctx // Reserved for future use.

	if err := validateRunID(m.RunID); err != nil {
		return fmt.Errorf("invalid run ID: %w", err)
	}
	if m.StartedAt.IsZero() {
		return errors.New("manifest StartedAt is required")
	}

	root, err := s.root()
	if err != nil {
		return fmt.Errorf("open investigations store: %w", err)
	}
	if err := osroot.MkdirAllNoSymlink(root, s.dirName, 0o750); err != nil {
		return fmt.Errorf("create investigations manifests dir: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(m, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal manifest: %w", err)
	}

	// 0o600: manifests embed the user-supplied investigation prompt and
	// (on terminal outcomes) the final findings body. Matches the mode
	// state.go uses for state.json.
	if err := jsonutil.WriteFileAtomicIn(root, s.name(manifestFilename(m)), data, 0o600); err != nil {
		return fmt.Errorf("write manifest: %w", err)
	}
	return nil
}

// List returns every manifest in the store sorted newest first by StartedAt.
// A missing directory is treated as an empty list (nil, nil) — useful for
// callers that want to render `--findings` even when no investigation has
// ever been run in this repo.
func (s *LocalManifestStore) List(ctx context.Context) ([]LocalManifest, error) {
	_ = ctx // Reserved for future use.

	root, err := s.root()
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("open investigations store: %w", err)
	}
	entries, err := osroot.ReadDirNoSymlinks(root, s.dirName)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read investigations manifests dir: %w", err)
	}

	manifests := make([]LocalManifest, 0, len(entries))
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		if !strings.HasSuffix(name, ".json") || strings.HasSuffix(name, ".tmp") {
			continue
		}
		b, readErr := osroot.ReadFileNoFollow(root, s.name(name))
		if readErr != nil {
			return nil, fmt.Errorf("read manifest %s: %w", name, readErr)
		}
		var m LocalManifest
		if err := json.Unmarshal(b, &m); err != nil {
			// Skip files we can't decode — they may be stale or
			// from a future schema. Listing must keep working.
			continue
		}
		// Skip manifests whose RunID is not a valid 12-hex id. A planted
		// manifest with e.g. "run_id":"../../.." would otherwise flow
		// through clean → RunDir → os.RemoveAll as a path-traversal target.
		// Validate at the source so no downstream consumer can be tricked.
		if err := validateRunID(m.RunID); err != nil {
			continue
		}
		manifests = append(manifests, m)
	}
	sort.SliceStable(manifests, func(i, j int) bool {
		return manifests[i].StartedAt.After(manifests[j].StartedAt)
	})
	return manifests, nil
}

// FindByRunID returns the manifest whose RunID equals runID. The bool
// reports whether a match was found; when false the returned manifest is
// the zero value. Returns an error only when the underlying directory read
// itself fails.
//
// Filenames are <timestamp>-<runID>.json, so the lookup is a single Glob +
// one file read rather than scanning every manifest in the directory.
func (s *LocalManifestStore) FindByRunID(ctx context.Context, runID string) (LocalManifest, bool, error) {
	_ = ctx
	if err := validateRunID(runID); err != nil {
		return LocalManifest{}, false, fmt.Errorf("invalid run ID: %w", err)
	}
	root, err := s.root()
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return LocalManifest{}, false, nil
		}
		return LocalManifest{}, false, fmt.Errorf("open investigations store: %w", err)
	}
	// A directory scan with a literal suffix match rather than filepath.Glob:
	// os.Root has no glob, and a literal match is the safer primitive anyway —
	// runID is validated above, but a pattern would let metacharacters in a
	// future caller's id match unrelated manifests.
	entries, err := osroot.ReadDirNoSymlinks(root, s.dirName)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return LocalManifest{}, false, nil
		}
		return LocalManifest{}, false, fmt.Errorf("read investigations manifests dir: %w", err)
	}
	suffix := "-" + runID + ".json"
	match := ""
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), suffix) {
			match = e.Name()
			break
		}
	}
	if match == "" {
		return LocalManifest{}, false, nil
	}
	b, err := osroot.ReadFileNoFollow(root, s.name(match))
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return LocalManifest{}, false, nil
		}
		return LocalManifest{}, false, fmt.Errorf("read manifest %s: %w", match, err)
	}
	var m LocalManifest
	if err := json.Unmarshal(b, &m); err != nil {
		return LocalManifest{}, false, fmt.Errorf("decode manifest %s: %w", match, err)
	}
	return m, true, nil
}

// ResolveByRunID matches a (possibly partial) run ID against the supplied
// manifest list. Exact match wins; otherwise unique-prefix wins. Returns
// a slice (always length 1 on success) so callers handle the not-found
// and ambiguous cases via the error.
//
// The shape mirrors what show and clean both want: an exact 12-hex match
// resolves O(1), a unique prefix expands to exactly one manifest, and any
// other case produces a user-readable error listing the candidates.

